# La configuración de classifier en el servidor de modelos (Triton). Formato de texto de protobuf.
# En C01: platform "tensorrt_plan", [3, 224, 224] → [500] y KIND_GPU en la T4.
name: "classifier"
platform: "onnxruntime_onnx"
max_batch_size: 32                         # el batch más grande que arma el servidor (el engine acepta hasta 32)
version_policy: { latest { num_versions: 1 } }
input  [ { name: "input"   data_type: TYPE_FP32  dims: [ 3, 32, 32 ] } ]   # sin el eje del batch: Triton le antepone -1
output [ { name: "logits"  data_type: TYPE_FP32  dims: [ 10 ] } ]
dynamic_batching {
  preferred_batch_size: [ 16, 32 ]
  max_queue_delay_microseconds: 2000       # espera hasta 2 ms a que lleguen más fotos para correrlas juntas
  default_queue_policy {
    timeout_action: REJECT
    default_timeout_microseconds: 100000   # 100 ms en la fila sin entrar al modelo: se rechaza (gateway.yaml: fila_triton)
  }
}
instance_group [ { count: 2  kind: KIND_CPU } ]   # dos copias del modelo
model_warmup [ {
  name: "ceros"  batch_size: 32  count: 3
  inputs { key: "input"  value: { data_type: TYPE_FP32  dims: [ 3, 32, 32 ]  zero_data: true } }
} ]

"""La revisión de cada foto, de lo más barato a lo más caro. Cada rechazo lleva su código HTTP.

Contrato:
- Rechazo(codigo, motivo): la excepción de todo lo que se rechaza; el gateway la convierte en la respuesta.
- revisar_tipo(content_type, tipos): 415 si no es uno de los tipos de gateway.yaml (ignora «; charset=…»).
- revisar_largo(content_length, max_bytes): 413 si el header Content-Length dice más que max_bytes, sin leer el body.
  Si el header no viene, no decide nada.
- leer_body(request, max_bytes): lee el body en pedazos y corta con 413 en cuanto pasa de max_bytes (el header puede
  mentir o no venir). Si quien llama se va a media subida, deja pasar ClientDisconnect (el gateway contesta 499).
- revisar_imagen(data, max_pixeles, max_proporcion): 400 si está vacía; abre SOLO el encabezado (Image.open no
  decodifica los píxeles) y da 400 si Pillow no la reconoce, 413 si ancho × alto pasa de max_pixeles y 400 si el lado
  largo pasa de max_proporcion veces el corto. Devuelve (ancho, alto).
- preparar(data): el decode y el preprocess del paquete compartido (preprocess.py, el mismo del entrenamiento). Si el
  archivo está corrupto o cortado, 400. Devuelve float32 [3, 32, 32].
- Image.MAX_IMAGE_PIXELS se fija en max_pixeles al arrancar: la red propia de Pillow, de respaldo.
"""
from __future__ import annotations

import io

import numpy as np
from PIL import Image, UnidentifiedImageError

from . import preprocess


class Rechazo(Exception):
    def __init__(self, codigo: int, motivo: str, reintentar: bool = False):
        super().__init__(motivo)
        self.codigo, self.motivo, self.reintentar = codigo, motivo, reintentar


def revisar_tipo(content_type: str | None, tipos: list[str]) -> str:
    tipo = (content_type or "").split(";")[0].strip().lower()
    if tipo not in tipos:
        raise Rechazo(415, f"tipo {tipo or '(sin Content-Type)'}: solo {', '.join(tipos)}")
    return tipo


def revisar_largo(content_length: str | None, max_bytes: int) -> None:
    if content_length is None:
        return
    try:
        n = int(content_length)
    except ValueError:
        raise Rechazo(400, f"Content-Length no es un número: {content_length!r}") from None
    if n > max_bytes:
        raise Rechazo(413, f"Content-Length {n} B: el máximo es {max_bytes} B")


async def leer_body(request, max_bytes: int) -> bytes:
    partes, n = [], 0
    async for trozo in request.stream():
        n += len(trozo)
        if n > max_bytes:
            raise Rechazo(413, f"el body pasa de {max_bytes} B (se cortó al leer)")
        partes.append(trozo)
    return b"".join(partes)


def revisar_imagen(data: bytes, max_pixeles: int, max_proporcion: float) -> tuple[int, int]:
    if not data:
        raise Rechazo(400, "body vacío")
    try:
        with Image.open(io.BytesIO(data)) as im:     # solo el encabezado: el ancho y el alto, sin decodificar
            w, h = im.size
    except Image.DecompressionBombError:
        raise Rechazo(413, f"más de {max_pixeles:,} píxeles (Pillow)") from None
    except (UnidentifiedImageError, OSError, ValueError):
        raise Rechazo(400, "no es una imagen que se pueda leer") from None
    if w * h > max_pixeles:
        raise Rechazo(413, f"{w} × {h} = {w * h:,} píxeles: el máximo es {max_pixeles:,}")
    if max(w, h) > max_proporcion * min(w, h):
        raise Rechazo(400, f"{w} × {h}: el lado largo pasa de {max_proporcion:g} veces el corto")
    return w, h


def preparar(data: bytes) -> np.ndarray:
    try:
        return preprocess.preprocess(data)
    except (OSError, ValueError, SyntaxError, Image.DecompressionBombError) as e:
        raise Rechazo(400, f"no se pudo decodificar la imagen ({type(e).__name__})") from None

"""Lo que comparten las pruebas: un Triton falso, las reglas, la ficha del modelo y fotos hechas al vuelo.

Contrato:
- TritonFalso tiene los mismos métodos asíncronos que el cliente real (get_model_metadata, is_model_ready, infer,
  close) y lanza las mismas excepciones, pero contesta lo que la prueba le pida: logits, una demora, un error, «no
  listo». Además revisa el nombre, el tipo y la forma del tensor que le mandan, como lo haría Triton.
- No abre ningún puerto: las pruebas corren sin Triton, sin GPU y sin red, en segundos.
"""
from __future__ import annotations

import asyncio
import io
import json
import struct
import zlib

import numpy as np
import pytest
from PIL import Image
from tritonclient.utils import InferenceServerException

from app.main import leer_reglas

LABELS = ["playeras", "pantalones", "sueteres", "vestidos", "abrigos",
          "sandalias", "camisas", "tenis", "bolsas", "botines"]


class Resultado:
    def __init__(self, y: np.ndarray):
        self.y = y

    def as_numpy(self, nombre: str) -> np.ndarray:
        return self.y


class TritonFalso:
    def __init__(self, logits=None, demora: float = 0.0, error: Exception | None = None, listo: bool = True,
                 demora_listo: float = 0.0, n_logits: int = 10):
        self.logits = np.array(logits if logits is not None else [0.5, 0.1, 0.2, 0.0, 0.3, 1.0, 0.4, 3.0, 0.2, 2.0], np.float32)
        self.demora, self.error, self.listo, self.demora_listo, self.n = demora, error, listo, demora_listo, n_logits
        self.vistos: list[tuple] = []
        self.cerrado = False

    async def get_model_metadata(self, nombre):
        return {"name": nombre, "versions": ["1"], "platform": "onnxruntime_onnx",
                "inputs": [{"name": "input", "datatype": "FP32", "shape": [-1, 3, 32, 32]}],
                "outputs": [{"name": "logits", "datatype": "FP32", "shape": [-1, self.n]}]}

    async def is_model_ready(self, nombre):
        await asyncio.sleep(self.demora_listo)
        return self.listo

    async def infer(self, model_name, inputs, outputs=None, request_id="", **kw):
        e = inputs[0]
        self.vistos.append((e.name(), e.datatype(), list(e.shape()), request_id))
        if e.name() != "input" or e.datatype() != "FP32" or list(e.shape())[1:] != [3, 32, 32]:
            raise InferenceServerException(f"unexpected shape for input '{e.name()}': {e.shape()}", status="400")
        if self.demora:
            await asyncio.sleep(self.demora)
        if self.error:
            raise self.error
        return Resultado(np.tile(self.logits, (list(e.shape())[0], 1)))

    async def close(self):
        self.cerrado = True


@pytest.fixture
def reglas():
    return leer_reglas()


@pytest.fixture
def modelo():
    s = json.dumps(LABELS, ensure_ascii=False) + "\n"
    import hashlib

    return {"modelo": "classifier", "version": 4, "model_version": "miniresnet-2026-10-01", "engine_sha256": "0" * 64,
            "labels": LABELS, "labels_sha256": hashlib.sha256(s.encode()).hexdigest(),
            "entrada": {"nombre": "input", "forma": [-1, 3, 32, 32]}, "salida": {"nombre": "logits", "forma": [-1, 10]}}


def foto(formato: str = "JPEG", lado: tuple[int, int] = (56, 56)) -> bytes:
    b = io.BytesIO()
    Image.new("RGB", lado, (120, 80, 40)).save(b, formato)
    return b.getvalue()


def png_solo_encabezado(ancho: int, alto: int) -> bytes:
    """Un PNG que dice medir ancho × alto y casi no trae píxeles: pesa ≈ 60 B. Image.open lo abre (lee el encabezado)."""
    def trozo(tipo, datos):
        return struct.pack(">I", len(datos)) + tipo + datos + struct.pack(">I", zlib.crc32(tipo + datos))
    return (b"\x89PNG\r\n\x1a\n" + trozo(b"IHDR", struct.pack(">IIBBBBB", ancho, alto, 8, 2, 0, 0, 0))
            + trozo(b"IDAT", zlib.compress(b"\x00" * 16)) + trozo(b"IEND", b""))
